/// <summary>
///     The <c>AVASalesLineBackOrderFrm_SalesLineDS_Extension</c> class is the extension for <c>SalesCopying</c>
/// </summary>
[ExtensionOf(formDataSourceStr(SalesCopying, CustInvoiceTrans))]
final class AVASalesCopyingFrm_CustInvoiceTransDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>executeQuery</c> method.
/// </summary>
void executeQuery()
{
    QueryBuildDataSource    locQBDS;
    QueryBuildRange         locQBR;

    locQBDS = this.queryBuildDataSource();
    locQBR  = SysQuery::findOrCreateRange(locQBDS, fieldNum(CustInvoiceTrans, AVAItemSetComponent));
    locQBR.value(SysQuery::valueNot(NoYes::Yes));

    next executequery();
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    CustInvoiceTrans    locCustInvoiceTrans;
    Common              locCommon;

    next init();

    locCustInvoiceTrans.clear();
    locCommon = locCustInvoiceTrans;

    element.avaSetFormObjectVisibility(locCommon);
}
